from qiskit import QuantumCircuit

def solve(n: int, o: QuantumCircuit) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    # uniform superposition
    for i in range(n):
        qc.h(i)

    # phase oracle
    qc.compose(o, inplace=True)

    # diffusion on qubits 0 and 1  -> 2|s><s|-I on these two qubits
    # H X CZ X H
    for i in (0, 1):
        qc.h(i)
    for i in (0, 1):
        qc.x(i)
    qc.cz(0, 1)
    for i in (0, 1):
        qc.x(i)
    for i in (0, 1):
        qc.h(i)

    return qc
